    CONSTRAINT ispm_rule_weights_severity_check CHECK (((severity)::text = ANY ((ARRAY['Critical'::character varying, 'High'::character varying, 'Medium'::character varying, 'Low'::character varying])::text[]))),
    CONSTRAINT ispm_rule_weights_weight_check CHECK ((rule_weight > (0)::numeric))
